"""Assemble reports/hawkins2023_replication_tables.md from results/hawkins2023/*.csv."""
import pandas as pd
from pathlib import Path
P = Path(__file__).resolve().parents[1]; R = P / 'results/hawkins2023'; L = []
def h(s): L.append(f'\n{s}\n')
def tab(df, ff='.3f'): L.append(df.to_markdown(index=False, floatfmt=ff)); L.append('')
h('# Hawkins et al. (2023) replication of the Collective-ID analyses — tables')
L.append('Generated by `scripts/75_hk_report.py`. Data: github.com/hawkrobe/emergent-sensing (Exp 1: 294 complete games, 682 participants, 5 min, binary hidden spotlight, click control; Exp 3: 224 games, 451 participants, 6 min, gradient field, keyboard; 8 Hz).')
h('## 1. Teacher (goal-direction model) population weights, shrinkage scale and split-half reliability'); tab(pd.read_csv(R / 'teacher_reliability.csv'))
h('## 2. Reliability (first vs second half, within experiment x group size x field)'); rel = pd.read_csv(R / 'reliability.csv')
tab(rel.pivot_table(index=['block', 'param'], columns='experiment', values='r_split').reset_index(), '.2f')
h('## 3. Transfer: out-of-fold r from first-half sources to second-half targets'); tr = pd.read_csv(R / 'transfer_r.csv')
tab(tr.pivot_table(index=['experiment', 'target'], columns='source', values='r').join(tr.groupby(['experiment', 'target']).noise_ceiling.first()).reset_index(), '.2f')
h('### 3b. Delta r vs first-half score (game-cluster bootstrap)'); d = pd.read_csv(R / 'transfer_delta.csv'); tab(d[d.source.isin(['z4', 'z4+teacher1', 'waiting'])])
h('## 4. Decomposition of second-half individual outcomes (participants in games with >= 2 players)'); tab(pd.read_csv(R / 'decomposition.csv'))
h('## 5. Group level'); tab(pd.read_csv(R / 'group_pred.csv')); tab(pd.read_csv(R / 'group_composition.csv'))
for e in [1, 3]:
    h(f'## 6. Search-state z loadings, Exp {e}'); L.append(pd.read_csv(R / f'z_loadings_exp{e}.csv', index_col=0).to_markdown()); L.append('')
open(P / 'reports/hawkins2023_replication_tables.md', 'w').write('\n'.join(L)); print('written')
